       panel in desktop mode, where `lg:` media queries never matched. -->
  <div class="h-full w-full min-h-0 overflow-hidden bg-base-200 text-base-content @container">
    <div class="h-full min-h-0 flex flex-col @5xl:flex-row">
      <SolopreneurSidebar :active-module="activeModule" />

