        <SolopreneurTopbar />

        <main class="flex-1 min-h-0 overflow-y-auto px-4 md:px-8 xl:px-10 py-6" role="main">
          <component :is="currentView" :key="activeModule" />
        </main>
      </div>
    </div>

    <SolopreneurModal />
  </div>
</template>
